const e=[{Claim:"Three divisions are printed: Pre-Teen (12 years of age and under), Teen (ages 13-18) and Open (any age). No lowest age is printed, so the Pre-Teen band starts at 5 and the Open band is 5-99 as placeholders; a coordinator should confirm them. The Open division is a common group that Pre-Teen and Teen contestants can also enter.",SourceType:"Primary - the event's own rules document",Source:"Stearns County Fair Amateur Talent Contest 2025 rules and registration form",Url:"https://stearnscountyfair.com/wp-content/uploads/2025/06/2025-Talent-Show-Entry-Form.pdf"},{Claim:"The contest has one kind of entry, a talent act (any type of performance; musical groups and vocalists are named). It is modelled as one competition, Talent Act, with a Solo and a Group age group per division so every group has a real participant type. The form does not print a solo/group choice; the split is a modelling choice.",SourceType:"Primary - the event's own rules document",Source:"Stearns County Fair Amateur Talent Contest 2025 rules and registration form",Url:"https://stearnscountyfair.com/wp-content/uploads/2025/06/2025-Talent-Show-Entry-Form.pdf"},{Claim:"Judging is on quality of performance, stage presence, entertainment value and selection, by three judges, with no printed marks per criterion, so no judging criteria are shipped. The time limit is 4 minutes. Prizes are cash: 1st $100, 2nd $50, 3rd $25 in each division.",SourceType:"Primary - the event's own rules document",Source:"Stearns County Fair Amateur Talent Contest 2025 rules and registration form",Url:"https://stearnscountyfair.com/wp-content/uploads/2025/06/2025-Talent-Show-Entry-Form.pdf"},{Claim:"Scope note: the Stearns County residency rule, the rule against being a current-year winner at another Minnesota county fair, the point deduction for going over the time limit, no lip sync, no vocals or background music, the minimum of five contestants per division (otherwise placed in Open), State Fair qualification for first-place winners, and cash prizes are rules the platform has no field for; they are kept as registration-page rules and are not enforced by the software.",SourceType:"Primary - the event's own rules document",Source:"Stearns County Fair Amateur Talent Contest 2025 rules and registration form",Url:"https://stearnscountyfair.com/wp-content/uploads/2025/06/2025-Talent-Show-Entry-Form.pdf"}],t="Built from the Stearns County Fair Amateur Talent Contest 2025 rules and registration form (image-only PDF, read by rendering the page; the second page is a faint mirrored back-bleed with no extra content). Left out: ranks and grades (prizes are cash amounts only, no points), judging criteria (no marks printed), the over-time point deduction amount (not printed), residency and winner rules, the five-contestant minimum, State Fair qualification. The lowest age is not printed (placeholder Pre-Teen 5-12, Open 5-99). Warning times are not printed and are set to 0. The registration deadline and contest date are blank on the scan and are not captured. Each division is split into Solo and Group groups as a modelling choice.",n=[{GroupName:"Pre-Teen Solo",AgeFrom:5,AgeTo:12,ParticipantTypeSetting:"Individual",ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/groups/primary.webp"},{GroupName:"Teen Solo",AgeFrom:13,AgeTo:18,ParticipantTypeSetting:"Individual",ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/groups/teen.webp"},{GroupName:"Open Solo",AgeFrom:5,AgeTo:99,ParticipantTypeSetting:"Individual",IsCommonSetting:"Yes",NoAgeIdPrefixSetting:"Yes",ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/groups/senior.webp"},{GroupName:"Pre-Teen Group",AgeFrom:5,AgeTo:12,ParticipantTypeSetting:"Team",ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/groups/team-open.webp"},{GroupName:"Teen Group",AgeFrom:13,AgeTo:18,ParticipantTypeSetting:"Team",ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/groups/team-open.webp"},{GroupName:"Open Group",AgeFrom:5,AgeTo:99,ParticipantTypeSetting:"Team",IsCommonSetting:"Yes",NoAgeIdPrefixSetting:"Yes",ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/groups/team-open.webp"}],a=[{CompetitionItem:0,Title:"Talent Act",Category:109,CategoryCategoryName:"Others",ScoreLabel:1,ScoreLabelLabel:"Marks",ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/items/kids-talent-contest.webp",TimeCalculation:"TotalTime"}],i=[{CompetitionItem:0,CompetitionItemTitle:"Talent Act",Group:0,GroupGroupName:"Pre-Teen Solo",ParticipantType:1,ParticipantTypeTitle:"Individual",Gender:3,GenderGenderTitle:"Both",Language:4,LanguageLanguageName:"Any/NA",Fees:0,MaximumMinutes:4,MaximumScore:100,MaximumSeconds:0,WarningMinute:0,WarningSecond:0,Order:1,ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/items/kids-talent-contest.webp"},{CompetitionItem:0,CompetitionItemTitle:"Talent Act",Group:0,GroupGroupName:"Teen Solo",ParticipantType:1,ParticipantTypeTitle:"Individual",Gender:3,GenderGenderTitle:"Both",Language:4,LanguageLanguageName:"Any/NA",Fees:0,MaximumMinutes:4,MaximumScore:100,MaximumSeconds:0,WarningMinute:0,WarningSecond:0,Order:2,ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/items/kids-talent-contest.webp"},{CompetitionItem:0,CompetitionItemTitle:"Talent Act",Group:0,GroupGroupName:"Open Solo",ParticipantType:1,ParticipantTypeTitle:"Individual",Gender:3,GenderGenderTitle:"Both",Language:4,LanguageLanguageName:"Any/NA",Fees:0,MaximumMinutes:4,MaximumScore:100,MaximumSeconds:0,WarningMinute:0,WarningSecond:0,Order:3,ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/items/kids-talent-contest.webp"},{CompetitionItem:0,CompetitionItemTitle:"Talent Act",Group:0,GroupGroupName:"Pre-Teen Group",ParticipantType:2,ParticipantTypeTitle:"Team",Gender:3,GenderGenderTitle:"Both",Language:4,LanguageLanguageName:"Any/NA",Fees:0,MaximumMinutes:4,MaximumScore:100,MaximumSeconds:0,WarningMinute:0,WarningSecond:0,Order:4,ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/items/kids-talent-contest.webp"},{CompetitionItem:0,CompetitionItemTitle:"Talent Act",Group:0,GroupGroupName:"Teen Group",ParticipantType:2,ParticipantTypeTitle:"Team",Gender:3,GenderGenderTitle:"Both",Language:4,LanguageLanguageName:"Any/NA",Fees:0,MaximumMinutes:4,MaximumScore:100,MaximumSeconds:0,WarningMinute:0,WarningSecond:0,Order:5,ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/items/kids-talent-contest.webp"},{CompetitionItem:0,CompetitionItemTitle:"Talent Act",Group:0,GroupGroupName:"Open Group",ParticipantType:2,ParticipantTypeTitle:"Team",Gender:3,GenderGenderTitle:"Both",Language:4,LanguageLanguageName:"Any/NA",Fees:0,MaximumMinutes:4,MaximumScore:100,MaximumSeconds:0,WarningMinute:0,WarningSecond:0,Order:6,ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/items/kids-talent-contest.webp"}],o={Evidence:e,MaintenanceNote:t,AgeWiseGroups:n,CompetitionItems:a,CompetitionsAssignedToGroup:i};export{n as AgeWiseGroups,a as CompetitionItems,i as CompetitionsAssignedToGroup,e as Evidence,t as MaintenanceNote,o as default};
